'use strict';
const followupLabels={pending:'Contato pendente',attempted:'Tentativa sem retorno',contacted:'Família contatada',monitoring:'Em acompanhamento',closed:'Encerrado pela equipe'};
const signalLabels={active:'Três ou mais faltas seguidas',returned:'Presença ou justificativa registrada depois',unconfirmed:'Há marcação posterior pendente',corrected:'Sequência corrigida',inactive:'Matrícula ou turma inativa'};
let attendanceReportOptions=null;
function reportFilters(){return Object.fromEntries(new FormData($('attendance-report-form')))}
function reportGroupOptions(){const unit=$('attendance-report-unit').value,select=$('attendance-report-group'),old=select.value;select.replaceChildren(el('option','Todas as turmas',{value:''}));for(const g of attendanceReportOptions.groups.filter(g=>!unit||g.unit===unit))select.append(el('option',classUnits[g.unit]+' · '+g.label+' · '+g.start_time+(g.active?'':' · Inativa'),{value:g.id}));if([...select.options].some(o=>o.value===old))select.value=old}
function attendanceCards(items){const box=el('div',undefined,{class:'cards'});for(const [label,value]of items){const card=el('div',undefined,{class:'card'});card.append(el('p',label),el('strong',String(value)));box.append(card)}return box}
async function attendanceAlertDetail(id){
 const {alert:a}=await api('/attendance-alerts/'+id),box=$('attendance-alert-detail');box.hidden=false;box.replaceChildren(el('h3',a.name+' · '+a.student_id),el('p',classUnits[a.unit]+' · '+a.label+' · '+a.streak+' faltas sem justificativa'),el('p',signalLabels[a.signal]+' · '+followupLabels[a.workflow]),el('p','Datas: '+a.evidence.map(e=>e.day.split('-').reverse().join('/')).join(', ')),el('p','Último responsável pelo acompanhamento: '+(a.owner_email||'Ainda não assumido')));
 const contact=a.contact||{};box.append(el('h4','Contato cadastrado'),phoneContact([contact.guardian_name,contact.guardian_phone,contact.guardian_email].filter(Boolean).join(' · ')||'Contato não cadastrado. A secretaria deve completar a ficha.',contact.guardian_phone,contact.guardian_name||'Responsável'));
 const suggestion='Olá, '+(contact.guardian_name||'família')+'! Aqui é a equipe Luta pela Comunidade. Sentimos falta de '+a.name+' nas últimas aulas. Gostaríamos de saber se está tudo bem e se há alguma dificuldade em que possamos ajudar para o retorno. Qual o melhor momento para conversarmos?';
 const preview=el('details');preview.append(el('summary','Sugestão de mensagem para a família'),el('p',suggestion));const copy=el('button','Copiar mensagem para revisar e enviar',{type:'button',class:'secondary'});copy.addEventListener('click',action(async()=>{await navigator.clipboard.writeText(suggestion);notice('Mensagem copiada. Revise e envie pelo canal combinado com a família.')}));preview.append(copy);box.append(preview);
 const sent=a.notifications.reduce((counts,n)=>(counts[n.status]=(counts[n.status]||0)+1,counts),{});box.append(el('p','Avisos à equipe: '+(sent.accepted||0)+' aceitos pelo serviço de email; '+((sent.pending||0)+(sent.retry||0))+' pendentes; '+(sent.review||0)+' precisam de revisão. Aceitação não confirma leitura ou entrega na caixa de entrada.',{class:'muted'}));
 const history=el('details');history.append(el('summary','Histórico de acompanhamento ('+a.history.length+')'));for(const h of a.history)history.append(el('p',new Date(h.created_at).toLocaleString('pt-BR')+' · '+h.actor_email+' · '+followupLabels[h.workflow]),el('p',h.note,{class:'preserve-lines'}));box.append(history);
 const form=el('form');field(form,'Situação do acompanhamento','workflow',a.workflow,{options:followupLabels});field(form,'Canal utilizado','channel','phone',{options:{phone:'Telefone',whatsapp:'WhatsApp',email:'Email',in_person:'Conversa presencial',internal:'Revisão interna da equipe'}});field(form,'Resultado','outcome','no_reply',{options:{no_reply:'Sem resposta',reached:'Conseguiu conversar',return_planned:'Retorno combinado',other:'Outro resultado'}});const note=longField(form,'Registro objetivo do contato ou providência','note');note.required=true;note.minLength=5;note.maxLength=1500;form.append(el('p','Registre o apoio combinado e a próxima ação. Não inclua diagnósticos ou conteúdo de atendimento clínico.',{class:'muted'}));field(form,'Próxima tentativa ou revisão','next_contact',a.next_contact,{type:'date',min:todayBR()});form.append(el('button','Salvar acompanhamento'));
 form.addEventListener('submit',action(async()=>{const p=await api('/attendance-alerts/'+id,{method:'POST',data:{...Object.fromEntries(new FormData(form)),version:a.version}});await loadAttendanceReport();await attendanceAlertDetail(id);document.dispatchEvent(new Event('portal:absence-followup-saved'));notice(p.message)}));box.append(form);box.focus({preventScroll:true});box.scrollIntoView({block:'start'});
}
async function loadAttendanceReport(){
 const f=reportFilters(),query=new URLSearchParams(f),r=await api('/attendance-report?'+query),box=$('attendance-report-results');box.replaceChildren(el('p','Período: '+r.from.split('-').reverse().join('/')+' a '+r.to.split('-').reverse().join('/')+' · Atualizado em '+new Date(r.generated_at).toLocaleString('pt-BR')));
 box.append(attendanceCards([['Alunos',r.totals.students],['Presenças',r.totals.present],['Faltas sem justificativa',r.totals.absent],['Justificadas',r.totals.justified],['Sem marcação',r.totals.unmarked],['Frequência registrada',r.totals.frequency===null?'Sem dados':r.totals.frequency+'%']]));
 box.append(el('p','Frequência = presenças ÷ (presenças + faltas + justificadas). Registros sem marcação ficam fora da porcentagem e não contam como falta. A base inclui apenas aulas abertas; canceladas ficam fora dos totais. Confira a cobertura antes de comparar turmas.',{class:'muted'}));
 const lessons=el('details');lessons.append(el('summary','Resumo das aulas ('+r.lessons.length+')'));for(const c of r.lessons){const line=el('article',undefined,{class:'report-record'});line.append(el('h4',c.day.split('-').reverse().join('/')+' · '+c.time+' · '+c.label),el('p',classUnits[c.unit]+(c.cancelled?' · Cancelada: '+c.cancellation_reason:' · '+c.marked+'/'+c.total+' marcações · '+c.present+' presentes · '+c.absent+' faltas · '+c.justified+' justificadas · '+c.unmarked+' pendentes')));lessons.append(line)}box.append(lessons);
 box.append(el('h3','Resumo por aluno e turma'));const search=field(box,'Buscar nome ou ID no relatório','report-search','',{type:'search'}),list=el('div',undefined,{class:'report-records'});box.append(list);
 const draw=()=>{const q=search.value.toLocaleLowerCase('pt-BR'),rows=r.summary.filter(s=>(s.name+' '+s.student_id).toLocaleLowerCase('pt-BR').includes(q));list.replaceChildren();for(const s of rows){const item=el('article',undefined,{class:'report-record'});item.append(el('h4',s.name+' · '+s.student_id),el('p',classUnits[s.unit]+' · '+s.class),el('p',s.present+' presenças · '+s.absent+' faltas · '+s.justified+' justificadas · '+s.unmarked+' sem marcação'),el('p','Frequência: '+(s.frequency===null?'sem dados':s.frequency+'%')+' · Preenchimento da chamada: '+(s.completion===null?'sem aulas':s.completion+'%')));list.append(item)}if(!rows.length)list.append(el('p','Nenhum aluno corresponde aos filtros.'))};search.addEventListener('input',draw);draw();
 const alertsBox=$('attendance-alert-list'),p=await api('/attendance-alerts?'+new URLSearchParams({unit:f.unit,group_id:f.group_id}));alertsBox.replaceChildren(el('p','Os alertas usam o histórico da turma e os filtros de unidade e turma acima. Não ficam limitados ao período do relatório.'));
 $('absence-rule-description').textContent='Regra do projeto: '+p.threshold+' faltas sem justificativa consecutivas na mesma turma. Presença, justificativa ou registro sem marcação interrompem a sequência. O alerta pede conferência e apoio à família; não aplica punição.';
 const active=p.alerts.filter(a=>a.signal==='active'&&a.workflow!=='closed');alertsBox.append(el('p',active.length+' alertas ativos · '+p.alerts.filter(a=>a.overdue).length+' revisões com prazo atingido',{role:'status'}));
 for(const a of p.alerts){const b=el('button',a.name+' · '+classUnits[a.unit]+' · '+a.label+' · '+a.streak+' faltas · '+signalLabels[a.signal]+' · '+followupLabels[a.workflow]+(a.overdue?' · Revisão pendente':''),{type:'button',class:'secondary registration-row'});b.addEventListener('click',action(()=>attendanceAlertDetail(a.id)));alertsBox.append(b)}if(!p.alerts.length)alertsBox.append(el('p','Nenhuma sequência confirmada de '+p.threshold+' faltas sem justificativa.'));
 const recipients=el('details');recipients.append(el('summary','Destinatários dos avisos da equipe'));for(const u of p.recipients)recipients.append(el('p',classUnits[u.unit]+': '+u.roles.map(r=>labels[r.role]+' '+r.count).join(' · ')));recipients.append(el('p','Somente contas ativas. Psicologia e assistência social precisam estar habilitadas e vinculadas ao núcleo. Se uma função estiver com zero, cadastre e habilite a pessoa para que receba os próximos avisos.'));alertsBox.append(recipients);
 if(['admin','secretary'].includes(me.role)){const {issues,settings}=await api('/rollcall-issues?'+new URLSearchParams({unit:f.unit,group_id:f.group_id})),target=$('rollcall-issue-list');target.replaceChildren(el('p','Verificação a cada cinco minutos, '+settings.grace_minutes+' minutos após o fim da aula. Configure os avisos e acompanhe o envio em Chamadas pendentes.'));
  for(const i of issues){const card=el('article',undefined,{class:'report-record'});card.append(el('h4',i.day.split('-').reverse().join('/')+' · '+i.label),el('p',classUnits[i.unit]+' · '+({open:'Pendente',resolved:'Resolvida',cancelled:'Cancelada'}[i.status])+' · '+i.marked+'/'+i.expected+' marcações'),el('p',i.reason+' · Professores: '+(i.teachers.map(t=>t.name).join(', ')||'Nenhum habilitado')));target.append(card)}if(!issues.length)target.append(el('p','Nenhuma ocorrência de chamada pendente.'));
  if(!$('rollcall-reports-link')){setupReports();const link=el('button','Consultar ocorrências de chamada pendente',{id:'rollcall-reports-link',type:'button',class:'secondary'});link.addEventListener('click',()=>showPanel('rollcall-area'));$('reports-area').prepend(link)}
 }
}
document.addEventListener('portal:loaded',action(async()=>{
 if(!['admin','secretary','psychologist','social_worker'].includes(me.role))return;
 attendanceReportOptions=await api('/attendance-report/options');if(!$('attendance-report-area')){
  const area=el('section',undefined,{id:'attendance-report-area'});$('team-area').before(area);area.append(el('h2','Relatório de presença e acompanhamento'),el('p','Confira as chamadas, identifique faltas consecutivas e organize o apoio à família.'));
  const form=el('form',undefined,{id:'attendance-report-form'}),grid=el('div',undefined,{class:'grid'});form.append(grid);field(grid,'Unidade do relatório','unit','',{options:{'':'Todas as unidades autorizadas',...Object.fromEntries(attendanceReportOptions.units.map(u=>[u,classUnits[u]]))},htmlId:'attendance-report-unit'});field(grid,'Turma do relatório','group_id','',{options:{'':'Todas as turmas'},htmlId:'attendance-report-group'});field(grid,'Início do período','from',todayBR().slice(0,7)+'-01',{type:'date',max:todayBR()}).required=true;field(grid,'Fim do período','to',todayBR(),{type:'date',max:todayBR()}).required=true;form.append(el('button','Atualizar relatório'));
  const excel=el('button','Exportar Excel (.xlsx)',{type:'button',class:'secondary'});excel.addEventListener('click',action(async()=>{download(await api('/attendance-report.xlsx?'+new URLSearchParams(reportFilters()),{blob:true}),'relatorio-presenca.xlsx');notice('Relatório Excel gerado com os filtros selecionados.')}));form.append(excel);form.addEventListener('submit',action(loadAttendanceReport));area.append(form,el('section',undefined,{id:'attendance-report-results'}),el('h3','Acompanhamento de faltas consecutivas'),el('p','',{id:'absence-rule-description'}),el('div',undefined,{id:'attendance-alert-list'}),el('section',undefined,{id:'attendance-alert-detail',hidden:'',tabindex:'-1'}));
  if(['admin','secretary'].includes(me.role))area.append(el('h3','Ocorrências administrativas: chamadas pendentes'),el('div',undefined,{id:'rollcall-issue-list'}));$('attendance-report-unit').addEventListener('change',reportGroupOptions);
 }if(me.role==='admin'&&!$('absence-settings')){const {mountAbsenceSettings}=await import('./absence-settings.js');await mountAbsenceSettings({api,el,field,action,notice,onSaved:loadAttendanceReport},$('attendance-report-area'))}reportGroupOptions();await loadAttendanceReport();
}));
document.addEventListener('portal:logout',()=>{$('attendance-report-area')?.remove();attendanceReportOptions=null});

document.addEventListener('portal:open-absence-alert',action(event=>attendanceAlertDetail(event.detail.id)));
